// `native` — build backend #2.
//
// Runs the game's OWN toolchain — whatever `build.command` /`run.command` the
// `.atelier/target.json` declares (`cargo build`, `go build`, `cmake --build`,
// `dotnet publish`, a shell script, …). The packager does not know the
// language or the engine; it invokes the project's command and collects the
// artifact. This is what makes the build side language-agnostic: NO per-language
// code lives here. The shared forge pre-flight runs BEFORE this backend (it
// produced the neutral manifest + the game's registry binding via its external
// emitter).
//
// Commands run through the shell (author-controlled build config, same trust as
// an npm script) with `stdio: 'inherit'` so the toolchain's output streams
// straight to the terminal.

import { join } from 'node:path';
import { execa } from 'execa';
import fse from 'fs-extra';
import { error, info, success } from '../utils/log.js';
import { readTargetDescriptor } from '../target/readTarget.js';
import type { BuildBackend } from './types.js';

export const nativeBackend: BuildBackend = {
  id: 'native',
  async dev(ctx) {
    // Dev for a native game: build, then launch it. A game with no `run`
    // command just builds (nothing to launch).
    await runBuild(ctx.appDir);
    const { run } = readTargetDescriptor(ctx.appDir);
    if (run === undefined) {
      info('No "run" command in target.json — built only (nothing to launch).');
      return;
    }
    await runCommand(ctx.appDir, run.command, 'Launching game');
  },
  async build(ctx) {
    await runBuild(ctx.appDir);
  },
};

async function runBuild(appDir: string): Promise<void> {
  const { build } = readTargetDescriptor(appDir);
  if (build === undefined) {
    error(
      "The 'native' build backend requires a \"build\" command in .atelier/target.json " +
        '(e.g. { "build": { "command": "cargo build --release", "artifact": "target/release/game" } }).',
    );
    process.exit(1);
  }
  await runCommand(appDir, build.command, 'Native build');

  // If the descriptor names the artifact, confirm it landed — the same
  // "verify the export exists" guard the web backend applies to `out/`.
  if (build.artifact !== undefined) {
    const artifactPath = join(appDir, build.artifact);
    if (!(await fse.pathExists(artifactPath))) {
      error(
        `Native build finished but the declared artifact was not found at ${artifactPath}. ` +
          'Check the "artifact" path in .atelier/target.json.',
      );
      process.exit(1);
    }
    success(`Native build complete. Artifact at ${build.artifact}.`);
    return;
  }
  success('Native build complete.');
}

async function runCommand(
  appDir: string,
  command: string,
  label: string,
): Promise<void> {
  info(`${label}: ${command}`);
  try {
    await execa(command, {
      cwd: appDir,
      stdio: 'inherit',
      shell: true,
    });
  } catch {
    error(`${label} failed: \`${command}\`. See its output above.`);
    process.exit(1);
  }
}
