// Web pipeline orchestrator.
//
// Sequences four steps for a production build:
//
//   1. Clean previous artifacts (`.next/`, `out/`).
//   2. Pre-flight: run `@unsupervised/forge` to compress assets and
//      regenerate the typed asset dictionary.
//   3. Run `next build`. With `output: 'export'` set in
//      `next.config.js`, Next.js emits a fully-static `out/` dir.
//   4. Verify the export landed and route it to the requested
//      target (web / Tauri / Capacitor).
//
// Dev mode runs forge in watch mode in parallel with next dev:
//
//   1. Initial synchronous `forge` run — guarantees `assets.ts`
//      exists and is fresh BEFORE next typegen / next dev boot,
//      avoiding a startup race on cold checkouts.
//   2. Spawn `forge --watch` in the background — chokidar-driven
//      incremental rebuilds whenever anything under `assets-raw/`
//      changes. Solves the previously-easy mistake of editing a
//      raw asset and forgetting to re-run the pipeline; the
//      generated `assets.ts` and the WebP/Ogg/GLB outputs are now
//      always in sync with the source files in dev.
//   3. Run `next dev` in the foreground. On exit (Ctrl-C, SIGINT),
//      the watcher subprocess is torn down via `subprocess.kill()`
//      in a `finally` block.
//
// Why every child process gets `stdio: 'inherit'`:
// the packager is a meta-tool — its job is to chain real tools
// and surface their output, not to massage it. forge's progress
// bars and Next's build summary should stream straight to the
// developer's terminal so a stuck encode or a TS error is
// visible without an extra log file.

import { nextWebBackend } from '../backends/nextWebBackend.js';
import { runForge, startForgeWatcher } from '../preflight/forge.js';

export type DevTarget = 'web' | 'tauri' | 'capacitor';
export type BuildTarget = 'web' | 'tauri' | 'ios' | 'android';

export interface WebPipelineArgs {
  /** Absolute path to the consuming app (where Next.js + forge
   *  scripts live). Always `process.cwd()` from the CLI's
   *  perspective; passed in explicitly so the pipeline stays
   *  testable without monkey-patching `process.cwd()`. */
  appDir: string;
  mode: 'dev' | 'build';
  target: DevTarget | BuildTarget;
}

/**
 * The web build: shared forge pre-flight, then the `next-web` backend. The
 * two steps are the seam — the pre-flight is backend-agnostic (a `native`
 * game gets the same forge run), and `nextWebBackend` is the reference
 * implementation of the build-backend interface. Composed here so the
 * tauri / capacitor pipelines that call `runWebPipeline` are unchanged.
 */
export async function runWebPipeline(args: WebPipelineArgs): Promise<void> {
  if (args.mode === 'dev') {
    await runForge(args.appDir);
    const watcher = startForgeWatcher(args.appDir);
    try {
      await nextWebBackend.dev({ appDir: args.appDir, target: args.target });
    } finally {
      // Tear down the forge watcher whether next dev exited cleanly
      // (Ctrl-C) or threw. `kill()` is a no-op on an already-dead process,
      // so the unconditional call is safe. Null when the app declares no
      // forge step — there's no watcher to tear down.
      watcher?.kill('SIGTERM');
    }
    return;
  }

  await runForge(args.appDir);
  await nextWebBackend.build({ appDir: args.appDir, target: args.target });
}
