// Native pipeline — the `buildBackend: "native"` path.
//
// Same shape as the web pipeline: shared forge pre-flight, then the backend.
// For a native game, forge's pre-flight emits the neutral manifest AND runs the
// game's external registry emitter (its `.atelier/target.json` names it), so the
// game's own build then compiles against a freshly generated binding. The
// `nativeBackend` runs the project's toolchain command; the packager stays
// language-agnostic.

import { nativeBackend } from '../backends/nativeBackend.js';
import { runForge } from '../preflight/forge.js';

export interface NativePipelineArgs {
  appDir: string;
  mode: 'dev' | 'build';
}

export async function runNativePipeline(
  args: NativePipelineArgs,
): Promise<void> {
  // Pre-flight forge once (manifest + the game's native registry binding).
  await runForge(args.appDir);

  const ctx = { appDir: args.appDir, target: 'native' as const };
  if (args.mode === 'dev') {
    await nativeBackend.dev(ctx);
  } else {
    await nativeBackend.build(ctx);
  }
}
