// Read a game's `.atelier/target.json` for the fields the packager acts on:
// `buildBackend` (routing) + `build` / `run` (the native backend's commands).
// A narrow, zero-dependency LOCAL MIRROR of @unsupervised/schemas' `GameTarget` — the
// packager keeps its commander/execa/fs-extra-only charter and never imports a
// `@unsupervised/*` package (it shells forge as a subprocess; the descriptor is a
// shared FILE contract, not shared code). @unsupervised/forge validates the FULL
// descriptor via the canonical schema.
//
// Absent descriptor ⇒ `next-web` with no commands, so every existing game is
// unchanged.

import { join } from 'node:path';
import fse from 'fs-extra';
import type { BuildBackendId } from '../backends/types.js';

export interface NativeCommand {
  command: string;
  artifact?: string;
}
export interface RunCommand {
  command: string;
  qa?: string;
}

export interface PackagerTarget {
  buildBackend: BuildBackendId;
  build?: NativeCommand;
  run?: RunCommand;
}

function descriptorPath(appDir: string): string {
  return join(appDir, '.atelier', 'target.json');
}

function readRaw(appDir: string): Record<string, unknown> | null {
  const path = descriptorPath(appDir);
  if (!fse.existsSync(path)) return null;
  return fse.readJsonSync(path) as Record<string, unknown>;
}

/** The build backend for an app dir. Missing/absent ⇒ `next-web`. An
 *  out-of-range value throws (a broken descriptor is a build-time bug). */
export function resolveBuildBackendId(appDir: string): BuildBackendId {
  const raw = readRaw(appDir);
  const backend = raw?.buildBackend;
  if (backend === undefined || backend === null) return 'next-web';
  if (backend === 'next-web' || backend === 'native') return backend;
  throw new Error(
    `Invalid buildBackend "${String(backend)}" in ${descriptorPath(appDir)}. ` +
      `Expected 'next-web' or 'native'.`,
  );
}

/** The full descriptor the packager needs: backend + native build/run
 *  commands. Absent ⇒ `{ buildBackend: 'next-web' }`. */
export function readTargetDescriptor(appDir: string): PackagerTarget {
  const raw = readRaw(appDir);
  const target: PackagerTarget = { buildBackend: resolveBuildBackendId(appDir) };

  const build = raw?.build;
  if (build !== undefined && build !== null) {
    const command = (build as Record<string, unknown>).command;
    if (typeof command !== 'string' || command.length === 0) {
      throw new Error(
        `target.json "build" requires a non-empty "command" (${descriptorPath(appDir)}).`,
      );
    }
    const artifact = (build as Record<string, unknown>).artifact;
    target.build = {
      command,
      ...(typeof artifact === 'string' ? { artifact } : {}),
    };
  }

  const run = raw?.run;
  if (run !== undefined && run !== null) {
    const command = (run as Record<string, unknown>).command;
    if (typeof command !== 'string' || command.length === 0) {
      throw new Error(
        `target.json "run" requires a non-empty "command" (${descriptorPath(appDir)}).`,
      );
    }
    const qa = (run as Record<string, unknown>).qa;
    target.run = { command, ...(typeof qa === 'string' ? { qa } : {}) };
  }

  return target;
}
