// `next-web` — build backend #1 (the reference).
//
// Runs Next.js: `next dev` (dev) or `next build` with `output: 'export'`
// producing a fully-static `out/` (build), then verifies the export landed
// and hands it to the requested native-shell target (web / tauri / ios /
// android). This is exactly what the web pipeline always did — extracted
// behind the `BuildBackend` seam so a `native` backend is a sibling, not a
// fork of this file. The shared forge pre-flight runs BEFORE this backend.

import { join } from 'node:path';
import { execa, ExecaError } from 'execa';
import fse from 'fs-extra';
import { error, info, success } from '../utils/log.js';
import type { BackendContext, BuildBackend } from './types.js';

export const nextWebBackend: BuildBackend = {
  id: 'next-web',
  async dev(ctx) {
    await runNextDev(ctx.appDir);
  },
  async build(ctx) {
    // Clean first so a previous build's stale chunks can't ghost into the
    // new one — a real footgun when bouncing between targets that produce
    // different output sets.
    await cleanCaches(ctx.appDir);
    await runNextBuild(ctx.appDir);
    await verifyAndRouteOutput(ctx.appDir, ctx.target);
  },
};

async function cleanCaches(appDir: string): Promise<void> {
  info('Cleaning previous build artifacts (.next/, out/)…');
  await Promise.all([
    fse.remove(join(appDir, '.next')),
    fse.remove(join(appDir, 'out')),
  ]);
}

async function runNextBuild(appDir: string): Promise<void> {
  info('Building Next.js static export…');
  try {
    await execa('npx', ['next', 'build'], {
      cwd: appDir,
      stdio: 'inherit',
      env: {
        ...process.env,
        NODE_ENV: 'production',
      },
    });
    success('Next.js build complete.');
  } catch {
    error('Next.js build failed.');
    process.exit(1);
  }
}

async function runNextDev(appDir: string): Promise<void> {
  info('Starting Next.js dev server…');
  try {
    await execa('npx', ['next', 'dev'], {
      cwd: appDir,
      stdio: 'inherit',
    });
  } catch (cause) {
    // Ctrl-C on the dev server arrives as a SIGINT-shaped ExecaError —
    // that's a clean shutdown, not a failure.
    if (cause instanceof ExecaError && (cause.isCanceled || cause.signal)) {
      return;
    }
    error('Next dev exited with error.');
    if (cause instanceof Error) error(cause.message);
    process.exit(1);
  }
}

async function verifyAndRouteOutput(
  appDir: string,
  target: BackendContext['target'],
): Promise<void> {
  const outPath = join(appDir, 'out');
  if (!(await fse.pathExists(outPath))) {
    error(
      `Expected static export at ${outPath} but none was found. Make sure \`output: 'export'\` is set in next.config.js.`,
    );
    process.exit(1);
  }

  switch (target) {
    case 'web':
      success('Web build complete. Static assets ready in ./out/');
      return;
    case 'tauri':
      // Routed through `runTauriPipeline` by `cli.ts` before we ever reach
      // the web pipeline as a sub-step; this branch only fires when web is
      // the outer pipeline and tauri is a downstream bundler consuming
      // `out/`. The bundling is the tauri pipeline's responsibility.
      success('Web build complete. Tauri bundling will continue from ./out/.');
      return;
    case 'ios':
    case 'android':
      // Same shape as the tauri branch: cli.ts routed the build through
      // `runCapacitorPipeline`, which composes the web pipeline + Capacitor's
      // native bundling. The web pipeline produced `out/`; the Capacitor
      // pipeline picks up and copies it into `.capacitor/www/` for `cap sync`.
      success(
        `Web build complete. Capacitor (${target}) bundling will continue from ./out/.`,
      );
      return;
    default:
      success('Web build complete. Static assets ready in ./out/');
      return;
  }
}
