// `packager` CLI entry point.
//
// Two commands today:
//
//   packager dev   --target web|tauri|capacitor
//   packager build --target web|tauri|ios|android
//
// `web` runs through `runWebPipeline` (Next.js static export).
// `tauri` runs through `runTauriPipeline` (web pipeline + Tauri
// 2 native shell). `capacitor` / `ios` / `android` run through
// `runCapacitorPipeline` (web pipeline + Capacitor 6 native
// shell — synthesized into `<app>/.capacitor/` from the
// packager-owned `capacitor-template/`). `ios` / `android` are
// the per-platform build targets; `capacitor` is the dev-mode
// alias that runs `next dev` + prints mobile-testing
// instructions.
//
// Working directory:
// `process.cwd()` is the consuming app (e.g. apps/dex). The
// orchestrator runs every child process from there, so paths like
// `./public`, `./out`, and `./assets-raw` resolve to the app.

import { Command } from 'commander';
import { runCapacitorPipeline } from './pipelines/capacitorPipeline.js';
import { runNativePipeline } from './pipelines/nativePipeline.js';
import { runTauriPipeline } from './pipelines/tauriPipeline.js';
import { runWebPipeline, type BuildTarget, type DevTarget } from './pipelines/webPipeline.js';
import { resolveBuildBackendId } from './target/readTarget.js';
import { error } from './utils/log.js';

const DEV_TARGETS: readonly DevTarget[] = ['web', 'tauri', 'capacitor'];
const BUILD_TARGETS: readonly BuildTarget[] = ['web', 'tauri', 'ios', 'android'];

const program = new Command();

program
  .name('packager')
  .description(
    'Universal build orchestrator: runs forge, then Next.js, then routes the static bundle to the requested target shell.',
  )
  .version('0.0.0');

program
  .command('dev')
  .description('Run the dev server with the requested target wrapper.')
  .option(
    '--target <target>',
    `dev target (${DEV_TARGETS.join(' | ')})`,
    'web',
  )
  .action(async (opts: { target: string }) => {
    // A `native` game builds through its own toolchain — the --target
    // native-shell axis (web/tauri/…) doesn't apply.
    if (resolveBuildBackendId(process.cwd()) === 'native') {
      await runNativePipeline({ appDir: process.cwd(), mode: 'dev' });
      return;
    }
    if (!isOneOf(opts.target, DEV_TARGETS)) {
      error(
        `Invalid --target "${opts.target}". Choose one of: ${DEV_TARGETS.join(', ')}.`,
      );
      process.exit(1);
    }
    if (opts.target === 'tauri') {
      await runTauriPipeline({ appDir: process.cwd(), mode: 'dev' });
      return;
    }
    if (opts.target === 'capacitor') {
      await runCapacitorPipeline({
        appDir: process.cwd(),
        invocation: { mode: 'dev' },
      });
      return;
    }
    await runWebPipeline({
      appDir: process.cwd(),
      mode: 'dev',
      target: opts.target,
    });
  });

program
  .command('build')
  .description('Run a production build for the requested target.')
  .option(
    '--target <target>',
    `build target (${BUILD_TARGETS.join(' | ')})`,
    'web',
  )
  .action(async (opts: { target: string }) => {
    if (resolveBuildBackendId(process.cwd()) === 'native') {
      await runNativePipeline({ appDir: process.cwd(), mode: 'build' });
      return;
    }
    if (!isOneOf(opts.target, BUILD_TARGETS)) {
      error(
        `Invalid --target "${opts.target}". Choose one of: ${BUILD_TARGETS.join(', ')}.`,
      );
      process.exit(1);
    }
    if (opts.target === 'tauri') {
      await runTauriPipeline({ appDir: process.cwd(), mode: 'build' });
      return;
    }
    if (opts.target === 'ios' || opts.target === 'android') {
      await runCapacitorPipeline({
        appDir: process.cwd(),
        invocation: { mode: 'build', platform: opts.target },
      });
      return;
    }
    await runWebPipeline({
      appDir: process.cwd(),
      mode: 'build',
      target: opts.target,
    });
  });

program.parseAsync(process.argv).catch((cause: unknown) => {
  error(cause instanceof Error ? (cause.stack ?? cause.message) : String(cause));
  process.exit(1);
});

/** Narrowing helper — keeps the two valid-targets comparisons
 *  type-safe without an `as` cast at every call site. */
function isOneOf<T extends string>(
  value: string,
  candidates: readonly T[],
): value is T {
  return (candidates as readonly string[]).includes(value);
}
