// The forge pre-flight — the shared, backend-agnostic first step of every
// build. It runs `@unsupervised/forge` (asset compression + the neutral manifest +
// the registry bindings) BEFORE any build backend (Next.js web export, a
// native toolchain, …) consumes its output. Hoisted out of the web pipeline
// so a `native` backend gets the exact same pre-flight for free.
//
// forge is always invoked as a subprocess (never a function call) — see
// packages/packager/CLAUDE.md. `stdio: 'inherit'` streams its progress
// straight to the developer's terminal.
//
// ── Not every app the packager builds is a game ──────────────────────
//
// The pre-flight used to be unconditional, on the reasoning that an app
// skipping forge ships stale or missing assets. That holds for a GAME. It
// does not hold for a TOOLING app: `apps/workbench` has no `assets-raw/`,
// no data map, and imports none of forge's generated types — its forge run
// emitted an all-`never` types file that nothing consumed.
//
// So the pre-flight now asks the app whether it has a forge step, and the
// app answers the only way it can: by declaring a `forge` script in its
// own package.json. That is the same contract the pre-flight already
// depended on (it shells `npm run forge`, not the forge binary), just
// checked instead of assumed — which is what turns "the app has no assets
// to build" from a hard abort into a skipped step.
//
// The check is deliberately NOT "does assets-raw/ exist": an app can point
// forge anywhere via the script's own flags, and an empty-but-present
// assets-raw/ is exactly the state a game sits in before its first asset
// lands. The script's presence is the app's declaration; the directory is
// an implementation detail of the script.

import { join } from 'node:path';
import { execa, type ResultPromise } from 'execa';
import fse from 'fs-extra';
import { error, info, success } from '../utils/log.js';

/**
 * Does this app's package.json declare a `forge` script?
 *
 * PURE over the parsed manifest so the decision is testable without a
 * fixture app on disk. A non-string or empty/whitespace-only value reads
 * as "no step": `npm run` treats an empty script as a no-op anyway, and
 * an app that wrote one meant to opt out.
 */
export function declaresForgeScript(pkg: unknown): boolean {
  if (typeof pkg !== 'object' || pkg === null) return false;
  const scripts = (pkg as { scripts?: unknown }).scripts;
  if (typeof scripts !== 'object' || scripts === null) return false;
  const forge = (scripts as { forge?: unknown }).forge;
  return typeof forge === 'string' && forge.trim().length > 0;
}

/**
 * Read the app's manifest and answer whether it has a forge step.
 *
 * An UNREADABLE package.json resolves to `true` — run forge — rather than
 * quietly skipping. "I couldn't read the manifest" is not "this app has no
 * assets": skipping on a failed read would let a game with a malformed
 * package.json build against stale assets silently, which is the exact bug
 * the unconditional pre-flight existed to prevent. Running instead surfaces
 * the problem loudly through npm's own error, one step earlier than the
 * build backend would.
 */
// Deliberately SYNCHRONOUS. `startForgeWatcher` returns execa's
// `ResultPromise`, which is itself a thenable — so if this check made that
// function `async`, `await startForgeWatcher(...)` at the call site would
// recursively unwrap the subprocess and block until the watcher EXITS,
// which for a watcher is never. Keeping the read sync keeps the factory
// sync. It costs one small file read at process start, in a CLI that
// already resolves the Tauri binary through a sync `require`.
function appHasForgeStep(appDir: string): boolean {
  try {
    const pkg = fse.readJsonSync(join(appDir, 'package.json')) as unknown;
    return declaresForgeScript(pkg);
  } catch {
    return true;
  }
}

/** One-shot forge run. Aborts the process on failure (build mode has no
 *  fallback — stale assets are a bug, not a warning). Skipped entirely for
 *  an app that declares no `forge` script. */
export async function runForge(appDir: string): Promise<void> {
  if (!appHasForgeStep(appDir)) {
    info('Pre-flight: no `forge` script in package.json — skipping asset pipeline.');
    return;
  }
  info('Pre-flight: running @unsupervised/forge…');
  try {
    await execa('npm', ['run', 'forge'], {
      cwd: appDir,
      stdio: 'inherit',
      // execa handles `.cmd` extension auto-resolution on Windows
      // — no `cross-env` shim required.
    });
    success('Forge complete.');
  } catch {
    error('Pre-flight Forge failed. Aborting build.');
    process.exit(1);
  }
}

/**
 * Spawn `forge --watch` in the background. Returns the running subprocess
 * so the caller can `.kill()` it on shutdown, or **null** when the app
 * declares no forge step (nothing to watch — callers use `watcher?.kill()`).
 *
 * The `--` separator forwards `--watch` to forge through `npm run` — npm
 * consumes its own flags up to the `--` and passes everything after it
 * through to the underlying script. The forge CLI runs an initial
 * synchronous pass first (redundant given the synchronous `runForge` we
 * just awaited, but cheap and idempotent) and then attaches its chokidar
 * watcher. From then on, any change under `assets-raw/` triggers an
 * incremental rebuild — no manual `pnpm forge` rerun needed.
 *
 * The subprocess is detached only at the OS level (default execa
 * behaviour); on parent exit, the OS reaps it. The dev pipeline
 * additionally `.kill('SIGTERM')`s it in a `finally` block, the
 * deterministic shutdown path for a clean Ctrl-C on next dev.
 */
export function startForgeWatcher(appDir: string): ResultPromise | null {
  if (!appHasForgeStep(appDir)) return null;
  info('Starting forge watcher (assets-raw/ → public/)…');
  return execa('npm', ['run', 'forge', '--', '--watch'], {
    cwd: appDir,
    stdio: 'inherit',
    // Don't let a watcher crash crash the dev server. We surface its output
    // via stdio:inherit so the developer sees the failure, but we don't
    // propagate the exit code into the packager — next dev keeps running on
    // the previous valid assets.ts.
    reject: false,
  });
}
