// Tauri (desktop native) pipeline orchestrator.
//
// Apps that adopt the packager get desktop binaries for free. The
// app itself ships ZERO Tauri boilerplate — no `src-tauri/`, no
// Cargo.toml, no Rust files, no icons. The packager owns the
// scaffold (under `packages/packager/tauri-template/`) and
// synthesizes it into `<app>/.tauri/` on each invocation. `.tauri/`
// is git-ignored cache, like `.next/` and `out/`.
//
// Apps that want branding overrides drop a `tauri.config.json` at
// the app root; the packager merges it over defaults derived from
// `package.json` (productName, identifier, version). Apps that want
// a custom icon drop `public/app-icon.png` (1024×1024 PNG); the
// packager regenerates platform-specific icons via `tauri icon`
// when that source changes.
//
// Dev mode:
//   1. Synthesize `.tauri/` from template (idempotent — no-op if
//      already current).
//   2. Generate platform icons via `tauri icon` if missing.
//   3. forge once (sync) — assets.ts is fresh BEFORE Next typegen.
//      Skipped for an app that declares no `forge` script (see
//      preflight/forge.ts — a tooling app is not a game).
//   4. spawn forge --watch (background subprocess), likewise skipped.
//   5. `tauri dev --config .tauri/tauri.conf.json` (foreground).
//      Tauri runs `next dev` via beforeDevCommand + opens a
//      webview at http://localhost:3000.
//   6. on exit, the forge watcher (if any) is torn down in `finally`.
//
// Build mode:
//   1. Synthesize `.tauri/` from template.
//   2. Generate platform icons if missing.
//   3. Delegate to `runWebPipeline({ mode: 'build', target: 'web' })`
//      to produce `out/`.
//   4. `tauri build` against the synthesized scaffold. Tauri
//      bundles `out/` as a native binary.
//   5. Report bundle output paths.
//
// Constraint: Tauri requires a Rust toolchain (cargo, rustc) +
// platform tools (Xcode CLT on macOS, MSVC on Windows,
// build-essential on Linux). The pipeline assumes these are
// installed. If `cargo` isn't on PATH the subprocess fails with
// a clear error and the user fixes their toolchain.

import { createHash } from 'node:crypto';
import { createRequire } from 'node:module';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { execa, ExecaError } from 'execa';
import fse from 'fs-extra';
import { runForge, startForgeWatcher } from '../preflight/forge.js';
import { error, info, success, warn } from '../utils/log.js';
import { runWebPipeline } from './webPipeline.js';

const require = createRequire(import.meta.url);

/** Default window dimensions if `tauri.config.json` doesn't override. */
const DEFAULT_WINDOW_WIDTH = 1280;
const DEFAULT_WINDOW_HEIGHT = 800;

export interface TauriPipelineArgs {
  /** Absolute path to the consuming app. Always `process.cwd()`
   *  from the CLI's perspective; passed in explicitly so the
   *  pipeline stays testable without monkey-patching cwd. */
  appDir: string;
  mode: 'dev' | 'build';
}

export async function runTauriPipeline(args: TauriPipelineArgs): Promise<void> {
  const cacheDir = join(args.appDir, '.tauri');
  const config = await readAppConfig(args.appDir);
  await synthesizeScaffold(args.appDir, cacheDir, config);
  await ensureIcons(args.appDir, cacheDir);

  const features = cargoFeaturesForConfig(config);

  if (args.mode === 'dev') {
    await runTauriDev(args.appDir, cacheDir, features);
    return;
  }

  await runTauriBuild(args.appDir, cacheDir, features);
}

// ────────────────────────────────────────────────────────────────
// Synthesis — write .tauri/ from packager-owned template
// ────────────────────────────────────────────────────────────────

export interface AppConfig {
  /** Tauri productName + bundle display name. Derived from
   *  package.json `name` unless `tauri.config.json` overrides. */
  productName: string;
  /** Reverse-DNS bundle identifier. Derived from name unless
   *  overridden. */
  identifier: string;
  /** Semver. Mirrors package.json version. */
  version: string;
  /** Cargo crate name (snake_case, no leading digits). Derived
   *  from name. */
  crateName: string;
  /** Window title displayed in the title bar. Defaults to
   *  productName. */
  title: string;
  width: number;
  height: number;
  shortDescription: string;
  longDescription: string;
  /** macOS title-bar style. `'Visible'` is the standard system
   *  title bar with traffic-light buttons + a title text band
   *  above the content. `'Transparent'` keeps the band but
   *  makes it transparent — the app's own background bleeds
   *  through. `'Overlay'` removes the band entirely + the
   *  traffic-light buttons overlay directly on the content;
   *  tooling apps wanting a unified background pick this. The
   *  app is responsible for adding a draggable region
   *  (`data-tauri-drag-region`) when using `Transparent` /
   *  `Overlay` so the user can still grab the window.
   *  Default: `'Visible'` (Tauri's own default). */
  titleBarStyle?: 'Visible' | 'Transparent' | 'Overlay';
  /** Hide the title text from the title bar. Only the traffic-
   *  light buttons remain visible (on macOS). Useful with
   *  `titleBarStyle: 'Overlay'` for the canonical "no title bar
   *  text" tooling-app look. Default: false. */
  hiddenTitle?: boolean;
  /** Open the window in TRUE fullscreen — it takes over the display, and on
   *  macOS gets its own Space with the menu bar hidden.
   *
   *  Right for a GAME, and for a tool the operator lives in all day. Consider
   *  `maximized` instead for anything used ALONGSIDE an editor or terminal:
   *  a macOS Space has to be swiped away from, where a maximized window is
   *  still just a window. Default: false. */
  fullscreen?: boolean;
  /** Open the window filling the available work area, still as an ordinary
   *  window — title bar present, other windows reachable, no macOS Space.
   *
   *  Ignored when `fullscreen` is true (fullscreen already fills the display,
   *  and Tauri applies it first). Default: false. */
  maximized?: boolean;
  /** Next.js dev port. Tauri's `beforeDevCommand` spawns
   *  `npx next dev --port <devPort>`; the webview loads
   *  `http://localhost:<devPort>`. Default 3000.
   *
   *  Override via `<app>/tauri.config.json` when an app
   *  needs to run concurrently with another Tauri-built app
   *  (each Tauri shell's webview hardcodes its own
   *  `devUrl`, so two apps sharing a port → the second-up
   *  webview loads the first-up app's content). Convention:
   *  workbench / tooling apps stay on 3000; games claim 3100+. */
  devPort?: number;
  /** Disable Turbopack in dev mode — adds `--webpack` to the
   *  spawned `next dev`. Default false (Turbopack on, Next 16's
   *  default).
   *
   *  Opt in when Turbopack's known lazy `public/` indexing
   *  breaks asset loading reliably — games with many
   *  large binary assets (multi-MB `.glb` models) sometimes
   *  hit 404s during the first ~30s of `next dev` boot before
   *  Turbopack has indexed `public/`. Webpack indexes
   *  synchronously at boot and avoids the race entirely; the
   *  cost is slower HMR rebuilds. */
  noTurbo?: boolean;
  /** Custom URL schemes to register for the deep-link plugin (e.g.
   *  `["atelier"]` → `atelier://…` links launch/reach the app). Rendered
   *  into the tauri.conf `plugins.deep-link.desktop.schemes` block.
   *  Default `[]` — games register no scheme, so the shared deep-link
   *  plugin is inert for them. Only the workbench uses it (OAuth /
   *  magic-link callback). */
  deepLinkSchemes?: string[];
  /** Compile the OS-keychain command surface (src/keychain.rs) into the
   *  binary + pull the `keyring` dependency, by building with
   *  `--features keychain`. Default false — games don't compile the
   *  keychain surface or take on keyring's platform build deps (notably
   *  libsecret on Linux). Only the workbench sets this (its secure
   *  TokenStore keeps the session in the OS credential vault). */
  keychain?: boolean;
}

/** The Cargo features the packager enables for this app, derived from
 *  its config. Pure + exported so the mapping is unit-testable without
 *  spawning cargo. `custom-protocol` is wired by the Tauri CLI itself,
 *  so it's not listed here. */
export function cargoFeaturesForConfig(config: AppConfig): string[] {
  const features: string[] = [];
  if (config.keychain === true) features.push('keychain');
  return features;
}

async function synthesizeScaffold(appDir: string, cacheDir: string, config: AppConfig): Promise<void> {
  info('Synthesizing Tauri scaffold into .tauri/…');
  const templateDir = locateTemplateDir();

  await fse.ensureDir(cacheDir);
  await fse.ensureDir(join(cacheDir, 'src'));
  await fse.ensureDir(join(cacheDir, 'capabilities'));
  await fse.ensureDir(join(cacheDir, 'icons'));

  // Templated files: substitute {{placeholders}} with config.
  await writeTemplated(
    join(templateDir, 'Cargo.toml.tpl'),
    join(cacheDir, 'Cargo.toml'),
    config,
  );
  await writeTemplated(
    join(templateDir, 'tauri.conf.json.tpl'),
    join(cacheDir, 'tauri.conf.json'),
    config,
  );

  // Static files: copy verbatim.
  await fse.copy(join(templateDir, 'src', 'main.rs'), join(cacheDir, 'src', 'main.rs'));
  // QA bridge plugin (Phase 2 of @unsupervised/qa-input-ws). Auto-shipped to every
  // game's synthesized scaffold so dev / playtest builds expose the
  // localhost-WebSocket QA bridge workbench connects to. The module is
  // `#[cfg(debug_assertions)]`-gated in main.rs so release builds drop
  // it entirely. See packages/qa-input-ws/CLAUDE.md for the contract.
  await fse.copy(
    join(templateDir, 'src', 'qa_bridge.rs'),
    join(cacheDir, 'src', 'qa_bridge.rs'),
  );
  // Keychain commands (OS credential-vault TokenStore backend). Copied
  // to every scaffold but compiled only under the `keychain` Cargo
  // feature (see src/keychain.rs). Games leave the feature off → the
  // file is present but never built.
  await fse.copy(
    join(templateDir, 'src', 'keychain.rs'),
    join(cacheDir, 'src', 'keychain.rs'),
  );
  await fse.copy(join(templateDir, 'build.rs'), join(cacheDir, 'build.rs'));
  await fse.copy(
    join(templateDir, 'capabilities', 'default.json'),
    join(cacheDir, 'capabilities', 'default.json'),
  );

  // Permission manifests for the inline qa_bridge plugin (Phase 2 of
  // @unsupervised/qa-input-ws). `tauri-build` discovers `<crate>/permissions/`
  // at compile time + makes the declared permissions available to
  // capability grants. Without this directory, Tauri 2's IPC layer
  // rejects every `plugin:qa_bridge|*` invoke with "Plugin not found"
  // because no permission manifest is registered.
  await fse.copy(
    join(templateDir, 'permissions'),
    join(cacheDir, 'permissions'),
  );

  // App-level capability overrides. Apps that need plugin permissions
  // (assets needs `fs:*` to read/write sidecars; future tooling apps
  // may need shell, dialog, etc.) drop one or more JSON files into
  // `<app>/tauri-capabilities/`. The synthesizer copies them
  // alongside `default.json`; Tauri loads every `*.json` in the
  // capabilities directory at build time. The template's
  // `default.json` stays the safe-by-default baseline; apps EXTEND
  // it instead of overriding it.
  await copyAppCapabilityOverrides(appDir, cacheDir);

  // gitignore so the cache stays out of git even if the dev
  // stages the directory by mistake.
  await fse.copy(join(templateDir, 'gitignore.tpl'), join(cacheDir, '.gitignore'));
}

/** Walk `<app>/tauri-capabilities/` (if present) and copy every
 *  `*.json` file into the synthesized `cacheDir/capabilities/`.
 *  Filenames are preserved so the merged set in the cache lists
 *  by identifier when Tauri compiles capability checks.
 *
 *  No-op when the directory is missing — most apps don't extend
 *  the default capabilities. */
async function copyAppCapabilityOverrides(
  appDir: string,
  cacheDir: string,
): Promise<void> {
  const overrideDir = join(appDir, 'tauri-capabilities');
  if (!(await fse.pathExists(overrideDir))) return;
  const dirents = await fse.readdir(overrideDir, { withFileTypes: true });
  let copied = 0;
  for (const dirent of dirents) {
    if (!dirent.isFile() || !dirent.name.endsWith('.json')) continue;
    await fse.copy(
      join(overrideDir, dirent.name),
      join(cacheDir, 'capabilities', dirent.name),
    );
    copied += 1;
  }
  if (copied > 0) {
    info(
      `Merged ${copied} app capabilit${copied === 1 ? 'y' : 'ies'} from tauri-capabilities/.`,
    );
  }
}

/** Locate the packager-owned tauri-template directory. Walks up
 *  from this file's location to handle both source (`src/pipelines/`)
 *  and built (`dist/`) layouts. */
function locateTemplateDir(): string {
  const here = dirname(fileURLToPath(import.meta.url));
  // From src/pipelines/ or dist/, walk up to the package root.
  // The template lives at <pkg>/tauri-template/.
  for (const candidate of [
    join(here, '..', '..', 'tauri-template'),
    join(here, '..', 'tauri-template'),
  ]) {
    if (fse.existsSync(candidate)) return candidate;
  }
  throw new Error(
    `[@unsupervised/packager] Could not locate tauri-template/ relative to ${here}.`,
  );
}

async function readAppConfig(appDir: string): Promise<AppConfig> {
  const pkgJson = await fse.readJSON(join(appDir, 'package.json')) as {
    name?: string;
    version?: string;
    description?: string;
  };

  const baseName = pkgJson.name ?? 'game';
  const productName = humanize(baseName);
  const crateName = sanitizeCrateName(baseName);
  const version = pkgJson.version ?? '0.0.0';
  const description = pkgJson.description ?? `A game built with the Atelier engine`;

  const defaults: AppConfig = {
    productName,
    identifier: `com.atelier.${crateName.replace(/_/g, '-')}`,
    version,
    crateName,
    title: productName,
    width: DEFAULT_WINDOW_WIDTH,
    height: DEFAULT_WINDOW_HEIGHT,
    shortDescription: description.slice(0, 80),
    longDescription: description,
    deepLinkSchemes: [],
    keychain: false,
  };

  // App override: `<app>/tauri.config.json` is merged over the
  // package.json-derived defaults. Apps stay clean — they ship
  // ONE optional file if they want branding, vs. an entire
  // src-tauri/ scaffold.
  const overridePath = join(appDir, 'tauri.config.json');
  if (await fse.pathExists(overridePath)) {
    info('Merging tauri.config.json overrides.');
    const override = (await fse.readJSON(overridePath)) as Partial<AppConfig>;
    return { ...defaults, ...override };
  }

  return defaults;
}

/** Cargo crate names: lowercase, snake_case, no leading digit. */
function sanitizeCrateName(name: string): string {
  let sanitized = name
    .replace(/^@[^/]+\//, '')          // strip scope
    .toLowerCase()
    .replace(/[^a-z0-9_]+/g, '_')
    .replace(/^_+|_+$/g, '');
  if (/^[0-9]/.test(sanitized)) sanitized = `app_${sanitized}`;
  return sanitized || 'game';
}

/** "_template-3d" → "Template 3D" — readable product / window name. */
function humanize(name: string): string {
  return name
    .replace(/^@[^/]+\//, '')
    .replace(/^_+/, '')
    .replace(/[-_]+/g, ' ')
    .replace(/\b\w/g, (c) => c.toUpperCase());
}

/** Write a template file with `{{KEY}}` substitutions. */
/** Pure `{{KEY}}` substitution over a template string. Exported for unit
 *  testing the substitution table (esp. the deep-link schemes). */
export function applyTemplateSubstitutions(tpl: string, config: AppConfig): string {
  return tpl
    .replace(/\{\{CRATE_NAME\}\}/g, config.crateName)
    .replace(/\{\{PRODUCT_NAME\}\}/g, escapeForJson(config.productName))
    .replace(/\{\{IDENTIFIER\}\}/g, config.identifier)
    .replace(/\{\{VERSION\}\}/g, config.version)
    .replace(/\{\{TITLE\}\}/g, escapeForJson(config.title))
    .replace(/\{\{WIDTH\}\}/g, String(config.width))
    .replace(/\{\{HEIGHT\}\}/g, String(config.height))
    .replace(/\{\{SHORT_DESCRIPTION\}\}/g, escapeForJson(config.shortDescription))
    .replace(/\{\{LONG_DESCRIPTION\}\}/g, escapeForJson(config.longDescription))
    .replace(/\{\{TITLE_BAR_STYLE\}\}/g, config.titleBarStyle ?? 'Visible')
    .replace(/\{\{HIDDEN_TITLE\}\}/g, String(config.hiddenTitle ?? false))
    .replace(/\{\{FULLSCREEN\}\}/g, String(config.fullscreen ?? false))
    // Suppressed under fullscreen so the emitted config can't ask for both —
    // Tauri would honour fullscreen and silently ignore this, which reads like
    // a bug when someone later diffs the generated file against the source.
    .replace(/\{\{MAXIMIZED\}\}/g, String(config.fullscreen === true ? false : (config.maximized ?? false)))
    .replace(/\{\{DEV_PORT\}\}/g, String(config.devPort ?? 3000))
    .replace(/\{\{NEXT_DEV_FLAGS\}\}/g, config.noTurbo === true ? ' --webpack' : '')
    // A JSON array literal for the deep-link plugin's schemes. `[]` for
    // games (no scheme registered → the plugin is inert).
    .replace(/\{\{DEEP_LINK_SCHEMES_JSON\}\}/g, JSON.stringify(config.deepLinkSchemes ?? []));
}

async function writeTemplated(
  src: string,
  dest: string,
  config: AppConfig,
): Promise<void> {
  const tpl = await fse.readFile(src, 'utf8');
  await fse.writeFile(dest, applyTemplateSubstitutions(tpl, config), 'utf8');
}

function escapeForJson(value: string): string {
  return value.replace(/\\/g, '\\\\').replace(/"/g, '\\"');
}

// ────────────────────────────────────────────────────────────────
// Icons — `tauri icon` against source PNG, mtime-cached
// ────────────────────────────────────────────────────────────────

/** Ensure platform-specific icons exist in `.tauri/icons/`.
 *  Apps can drop their own `public/app-icon.png` to override the
 *  packager's default placeholder; we hash the source so a
 *  branding swap regenerates the platform binaries on next build. */
async function ensureIcons(appDir: string, cacheDir: string): Promise<void> {
  const templateDir = locateTemplateDir();
  const sourceIcon = await pickSourceIcon(appDir, templateDir);
  const iconsDir = join(cacheDir, 'icons');
  const hashFile = join(iconsDir, '.source-hash');

  const sourceHash = await hashFileContents(sourceIcon);
  const cachedHash = (await fse.pathExists(hashFile))
    ? await fse.readFile(hashFile, 'utf8')
    : '';

  const platformIcons = [
    join(iconsDir, '32x32.png'),
    join(iconsDir, '128x128.png'),
    join(iconsDir, '128x128@2x.png'),
    join(iconsDir, 'icon.icns'),
    join(iconsDir, 'icon.ico'),
  ];
  const allPresent = await Promise.all(platformIcons.map((p) => fse.pathExists(p)));

  if (cachedHash === sourceHash && allPresent.every(Boolean)) {
    return; // Icons are current; skip the regeneration step.
  }

  // Copy the source into the icons dir so `tauri icon` has a
  // predictable path to read.
  const stagedSource = join(iconsDir, 'icon.png');
  await fse.copy(sourceIcon, stagedSource);

  info('Generating platform-specific icons via `tauri icon`…');
  try {
    await execa(resolveTauriCli(), ['icon', stagedSource, '--output', iconsDir], {
      cwd: cacheDir,
      stdio: 'inherit',
    });
    await fse.writeFile(hashFile, sourceHash, 'utf8');
    success('Icons generated.');
  } catch (cause) {
    error('`tauri icon` failed.');
    if (cause instanceof Error) error(cause.message);
    process.exit(1);
  }
}

async function pickSourceIcon(appDir: string, templateDir: string): Promise<string> {
  // App-level override: <app>/public/app-icon.png
  const appOverride = join(appDir, 'public', 'app-icon.png');
  if (await fse.pathExists(appOverride)) return appOverride;
  // Default placeholder shipped with the packager.
  return join(templateDir, 'icons', 'icon.png');
}

async function hashFileContents(path: string): Promise<string> {
  const buf = await fse.readFile(path);
  return createHash('sha256').update(buf).digest('hex');
}

// ────────────────────────────────────────────────────────────────
// Dev
// ────────────────────────────────────────────────────────────────

async function runTauriDev(appDir: string, cacheDir: string, features: string[]): Promise<void> {
  await runForge(appDir);
  const watcher = startForgeWatcher(appDir);

  try {
    info('Starting Tauri dev (next dev → webview)…');
    await execa(
      resolveTauriCli(),
      ['dev', '--config', join(cacheDir, 'tauri.conf.json'), ...featureArgs(features)],
      {
        cwd: cacheDir,
        stdio: 'inherit',
      },
    );
  } catch (cause) {
    if (cause instanceof ExecaError && (cause.isCanceled || cause.signal)) {
      return; // Clean Ctrl-C shutdown.
    }
    error('Tauri dev exited with error.');
    if (cause instanceof Error) error(cause.message);
    process.exit(1);
  } finally {
    // Null when the app declares no forge step — nothing to tear down.
    watcher?.kill('SIGTERM');
  }
}

// ────────────────────────────────────────────────────────────────
// Build
// ────────────────────────────────────────────────────────────────

async function runTauriBuild(appDir: string, cacheDir: string, features: string[]): Promise<void> {
  // The web pipeline produces <app>/out/, which tauri.conf.json's
  // `frontendDist: '../out'` references. Compose, don't reimplement.
  info('Building static frontend before Tauri bundling…');
  await runWebPipeline({ appDir, mode: 'build', target: 'web' });

  info('Bundling Tauri desktop binary (cargo + platform toolchain)…');
  try {
    await execa(
      resolveTauriCli(),
      ['build', '--config', join(cacheDir, 'tauri.conf.json'), ...featureArgs(features)],
      {
        cwd: cacheDir,
        stdio: 'inherit',
      },
    );
    success('Tauri build complete.');
  } catch (cause) {
    error('Tauri build failed.');
    if (cause instanceof Error) error(cause.message);
    process.exit(1);
  }

  await reportBundleOutputs(cacheDir);
}

async function reportBundleOutputs(cacheDir: string): Promise<void> {
  const bundleRoot = join(cacheDir, 'target', 'release', 'bundle');
  if (!(await fse.pathExists(bundleRoot))) {
    warn(
      `Expected bundle output at ${bundleRoot} but none was found. The tauri CLI may have logged the failure above.`,
    );
    return;
  }
  const platforms = await fse.readdir(bundleRoot);
  if (platforms.length === 0) {
    warn('Bundle directory exists but is empty.');
    return;
  }
  info(`Bundle output: ${bundleRoot}`);
  for (const platform of platforms) {
    info(`  ${platform}/`);
  }
}

// ────────────────────────────────────────────────────────────────
// Helpers
// ────────────────────────────────────────────────────────────────

/** The `tauri dev|build` CLI args that enable the given Cargo features
 *  (forwarded to cargo). Empty when there are none, so the common case
 *  (games) adds nothing to the command line. */
function featureArgs(features: string[]): string[] {
  return features.length > 0 ? ['--features', features.join(',')] : [];
}

/** Resolve the path to the `tauri` binary shipped by
 *  `@tauri-apps/cli`. Lets us invoke Tauri without requiring apps
 *  to install the CLI themselves — `@unsupervised/packager` owns the
 *  dependency. */
function resolveTauriCli(): string {
  try {
    // `@tauri-apps/cli` ships a `package.json` with a `bin.tauri`
    // entry pointing at the platform-specific binary. Resolving
    // the package's manifest lets us derive the bin path
    // robustly across pnpm hoisting layouts.
    const cliPkgPath = require.resolve('@tauri-apps/cli/package.json');
    const cliPkg = require(cliPkgPath) as { bin?: { tauri?: string } | string };
    const cliDir = dirname(cliPkgPath);
    const binRel = typeof cliPkg.bin === 'string' ? cliPkg.bin : cliPkg.bin?.tauri;
    if (!binRel) {
      throw new Error('@tauri-apps/cli has no `bin.tauri` entry.');
    }
    return join(cliDir, binRel);
  } catch (cause) {
    error('Could not resolve @tauri-apps/cli.');
    error('Make sure @unsupervised/packager was installed with its dependencies (re-run `pnpm install`).');
    if (cause instanceof Error) error(cause.message);
    process.exit(1);
  }
}

