// Tiny prefixed console helpers backed by picocolors.
//
// Every line the packager prints starts with `[Packager]` so a
// developer running `npm run build:web` sees a clear diff between
// our output and the streamed-through output of `next build` /
// `forge` (which carry their own prefixes). picocolors is a
// 0-dep, ~3KB wrapper over ANSI escape codes — drop-in chalk
// replacement chosen because we don't need any of chalk's
// template-literal sugar.

import pc from 'picocolors';

const PREFIX = pc.cyan('[Packager]');

export function info(message: string): void {
  console.log(`${PREFIX} ${message}`);
}

export function success(message: string): void {
  console.log(`${PREFIX} ${pc.green(message)}`);
}

export function warn(message: string): void {
  console.warn(`${PREFIX} ${pc.yellow(message)}`);
}

export function error(message: string): void {
  console.error(`${PREFIX} ${pc.red(message)}`);
}

export function dim(message: string): void {
  console.log(`${PREFIX} ${pc.dim(message)}`);
}
