// Capacitor (iOS + Android native) pipeline orchestrator.
//
// Apps that adopt the packager get mobile native binaries for free.
// The app itself ships ZERO Capacitor boilerplate — no
// `capacitor.config.json`, no `ios/`, no `android/`, no Capacitor
// dependencies. The packager owns the scaffold (under
// `packages/packager/capacitor-template/`) and synthesizes it into
// `<app>/.capacitor/` on each invocation. `.capacitor/` is
// git-ignored cache, like `.next/` and `.tauri/`.
//
// Apps that want branding overrides drop a `capacitor.config.json`
// at the app root; the packager merges it over defaults derived
// from `package.json` (appId from `com.atelier.<name>`, appName from
// `name`, version). Apps that want a custom icon drop
// `public/app-icon.png` (square PNG, ≥ 1024×1024); the packager
// regenerates platform-specific icons via the `@capacitor/assets`
// CLI when that source changes.
//
// Why a SEPARATE `.capacitor/` shell (vs. installing Capacitor in
// the app's node_modules):
//
//   Capacitor's generated `ios/` + `android/` native projects
//   contain relative path references to `node_modules/@capacitor/ios`
//   and `node_modules/@capacitor/android` IN THE SAME DIRECTORY.
//   Putting the shell at `<app>/.capacitor/` means the generated
//   `ios/`+`android/` see their sibling `node_modules/` and link
//   cleanly. Apps stay free of Capacitor deps; the packager owns
//   the Capacitor version.
//
// Pipeline by mode + target:
//
//   dev --target capacitor:
//     Runs the web pipeline (next dev) and prints a one-line note
//     about how to test on a real device (PWA via `Add to Home
//     Screen`, or a debug build via `packager build --target ios|android`).
//     Capacitor's live-reload-to-simulator path requires an iOS /
//     Android dev environment to be set up out-of-band; first-class
//     wiring is deferred until apps push for it.
//
//   build --target ios:
//     1. Synthesize `.capacitor/` shell.
//     2. `npm install` inside `.capacitor/` (cached via
//        `node_modules/.installed-marker`).
//     3. Regenerate platform icons if the source PNG changed.
//     4. Web pipeline build → `<app>/out/`.
//     5. Copy `out/` → `.capacitor/www/`.
//     6. `npx cap add ios` (cached — skipped if `.capacitor/ios/`
//        already exists).
//     7. `npx cap sync ios` (always; updates plugins, copies web).
//     8. `xcodebuild -workspace ios/App/App.xcworkspace -scheme
//        App -configuration Release -sdk iphonesimulator
//        -derivedDataPath build`. Produces an unsigned `App.app`
//        runnable in the iOS Simulator. App Store submission
//        requires opening the project in Xcode + configuring
//        signing + archiving — documented in CLAUDE.md.
//
//   build --target android:
//     1-7. Same shape as iOS, with `cap add android` / `cap sync
//          android`.
//     8. `./gradlew assembleDebug` inside `android/`. Produces a
//        debug-signed `.apk` runnable on real devices + emulator.
//        Release signing (Play Store upload) requires a keystore +
//        signing config — documented in CLAUDE.md.
//
// Toolchain requirements (user-side):
//   - iOS: macOS host + Xcode (`xcode-select --install` for CLT).
//   - Android: JDK 17 + Android Studio (with SDK + build-tools
//     installed) + `ANDROID_HOME` env var.
//
// The packager doesn't try to install these; it surfaces the
// underlying CLI's error verbatim via `stdio: 'inherit'`.

import { createHash } from 'node:crypto';
import { existsSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { execa, ExecaError } from 'execa';
import fse from 'fs-extra';
import { error, info, success, warn } from '../utils/log.js';
import { runWebPipeline } from './webPipeline.js';

/** Default background color baked into the platform shells. Apps
 *  override via `capacitor.config.json`. */
const DEFAULT_BACKGROUND_HEX = '#0b1020';

/** Capacitor target platforms the build pipeline handles. */
export type CapacitorPlatform = 'ios' | 'android';

export type CapacitorPipelineMode =
  | { mode: 'dev' }
  | { mode: 'build'; platform: CapacitorPlatform };

export interface CapacitorPipelineArgs {
  /** Absolute path to the consuming app. Always `process.cwd()`
   *  from the CLI's perspective; passed in explicitly so the
   *  pipeline stays testable without monkey-patching cwd. */
  appDir: string;
  /** Discriminated mode descriptor. `'dev'` runs the web pipeline
   *  dev mode + prints mobile-testing instructions; `'build'`
   *  produces the requested platform's native binary. */
  invocation: CapacitorPipelineMode;
}

export async function runCapacitorPipeline(
  args: CapacitorPipelineArgs,
): Promise<void> {
  const cacheDir = join(args.appDir, '.capacitor');

  if (args.invocation.mode === 'dev') {
    await runCapacitorDev(args.appDir);
    return;
  }

  const platform = args.invocation.platform;
  await assertHostSupports(platform);
  await synthesizeScaffold(args.appDir, cacheDir);
  await installShellDeps(cacheDir);
  await ensureAssets(args.appDir, cacheDir);

  info('Building static frontend before Capacitor packaging…');
  await runWebPipeline({ appDir: args.appDir, mode: 'build', target: platform });

  await copyWebOutputToShell(args.appDir, cacheDir);
  await ensurePlatform(cacheDir, platform);
  await runCapSync(cacheDir, platform);

  if (platform === 'ios') {
    await runIosBuild(cacheDir);
  } else {
    await runAndroidBuild(cacheDir);
  }

  await reportBundleOutputs(cacheDir, platform);
}

// ────────────────────────────────────────────────────────────────
// Pure helpers (testable without spinning up Capacitor)
// ────────────────────────────────────────────────────────────────

export interface AppPackageMetadata {
  name?: string;
  version?: string;
  description?: string;
}

export interface CapacitorAppConfig {
  /** Reverse-DNS bundle identifier (Capacitor `appId`). */
  appId: string;
  /** Human-readable app name (Capacitor `appName`). Shown on the
   *  home screen + in the app switcher. */
  appName: string;
  /** Semver from package.json. */
  version: string;
  /** Internal `name` field in `.capacitor/package.json`. npm-safe. */
  projectName: string;
  /** Background color baked into the iOS / Android shell. Apps
   *  override via the optional `capacitor.config.json`. */
  backgroundHex: string;
}

/** Public-facing override shape — what apps can declare in
 *  `<app>/capacitor.config.json`. Every field is optional; missing
 *  fields fall through to `package.json`-derived defaults. */
export interface CapacitorConfigOverride {
  appId?: string;
  appName?: string;
  backgroundHex?: string;
}

/** Derive a `CapacitorAppConfig` from the app's `package.json` and
 *  optional `capacitor.config.json` override. Pure — no I/O. */
export function deriveCapacitorAppConfig(
  pkg: AppPackageMetadata,
  override: CapacitorConfigOverride = {},
): CapacitorAppConfig {
  const baseName = pkg.name ?? 'game';
  const projectName = sanitizeProjectName(baseName);
  const appName = override.appName ?? humanizeAppName(baseName);
  const defaultAppId = `com.atelier.${sanitizeAppIdSegment(baseName)}`;
  return {
    appId: override.appId ?? defaultAppId,
    appName,
    version: pkg.version ?? '0.0.0',
    projectName,
    backgroundHex: override.backgroundHex ?? DEFAULT_BACKGROUND_HEX,
  };
}

/** Validate a candidate appId. Capacitor accepts reverse-DNS
 *  strings: dot-separated segments, each segment starts with a
 *  letter and contains only letters / digits / underscores. Throws
 *  with a clear message if invalid. */
export function assertValidAppId(appId: string): void {
  // Empty / no-dot strings are rejected by Capacitor's own
  // validators at runtime; failing fast here gives a clearer
  // pointer ("your appId is invalid because…").
  if (!/^[a-zA-Z][a-zA-Z0-9_]*(\.[a-zA-Z][a-zA-Z0-9_]*)+$/.test(appId)) {
    throw new Error(
      `[@unsupervised/packager] Invalid Capacitor appId "${appId}". ` +
        'appId must be reverse-DNS (e.g. "com.studio.my-game"), ' +
        "each segment starting with a letter and containing only " +
        "letters / digits / underscores. Set 'appId' in " +
        '<app>/capacitor.config.json to override.',
    );
  }
}

/** npm-safe project name. Lowercase; replace non-alphanumeric runs
 *  with single hyphens; strip leading non-alpha; cap at 214 chars
 *  (npm's hard limit). */
export function sanitizeProjectName(name: string): string {
  const lowered = name
    .replace(/^@[^/]+\//, '') // strip npm scope
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '');
  const stripped = lowered.replace(/^[^a-z]+/, '');
  const fallback = stripped || 'game';
  return fallback.slice(0, 214);
}

/** Sanitize the trailing segment of a default reverse-DNS appId.
 *  Lowercase, alphanumeric + underscore, must start with a letter.
 *  The leading `com.atelier.` prefix guarantees ≥ 2 segments. */
export function sanitizeAppIdSegment(name: string): string {
  let s = name
    .replace(/^@[^/]+\//, '')
    .toLowerCase()
    .replace(/[^a-z0-9_]+/g, '_')
    .replace(/^_+|_+$/g, '');
  if (s.length === 0 || /^[0-9]/.test(s)) s = `app_${s}`;
  return s;
}

/** "_template-3d" → "Template 3D" — readable app display name. */
export function humanizeAppName(name: string): string {
  return name
    .replace(/^@[^/]+\//, '')
    .replace(/^_+/, '')
    .replace(/[-_]+/g, ' ')
    .replace(/\b\w/g, (c) => c.toUpperCase());
}

// ────────────────────────────────────────────────────────────────
// Synthesis — write .capacitor/ from packager-owned template
// ────────────────────────────────────────────────────────────────

async function synthesizeScaffold(
  appDir: string,
  cacheDir: string,
): Promise<void> {
  info('Synthesizing Capacitor scaffold into .capacitor/…');
  const config = await readAppConfig(appDir);
  assertValidAppId(config.appId);
  const templateDir = locateTemplateDir();

  await fse.ensureDir(cacheDir);

  await writeTemplated(
    join(templateDir, 'capacitor.config.json.tpl'),
    join(cacheDir, 'capacitor.config.json'),
    config,
  );
  await writeTemplated(
    join(templateDir, 'package.json.tpl'),
    join(cacheDir, 'package.json'),
    config,
  );
  await fse.copy(
    join(templateDir, 'gitignore.tpl'),
    join(cacheDir, '.gitignore'),
  );
}

async function readAppConfig(appDir: string): Promise<CapacitorAppConfig> {
  const pkg = (await fse.readJSON(
    join(appDir, 'package.json'),
  )) as AppPackageMetadata;

  const overridePath = join(appDir, 'capacitor.config.json');
  let override: CapacitorConfigOverride = {};
  if (await fse.pathExists(overridePath)) {
    info('Merging capacitor.config.json overrides.');
    override = (await fse.readJSON(overridePath)) as CapacitorConfigOverride;
  }
  return deriveCapacitorAppConfig(pkg, override);
}

/** Locate the packager-owned capacitor-template directory. Walks
 *  up from this file's location to handle both source
 *  (`src/pipelines/`) and built (`dist/`) layouts. */
function locateTemplateDir(): string {
  const here = dirname(fileURLToPath(import.meta.url));
  for (const candidate of [
    join(here, '..', '..', 'capacitor-template'),
    join(here, '..', 'capacitor-template'),
  ]) {
    if (existsSync(candidate)) return candidate;
  }
  throw new Error(
    `[@unsupervised/packager] Could not locate capacitor-template/ relative to ${here}.`,
  );
}

/** Apply `{{KEY}}` substitution to a template file's contents and
 *  write to `dest`. Mirrors the Tauri pipeline's templating helper
 *  exactly so contributors recognize the pattern. */
async function writeTemplated(
  src: string,
  dest: string,
  config: CapacitorAppConfig,
): Promise<void> {
  const tpl = await fse.readFile(src, 'utf8');
  const substituted = tpl
    .replace(/\{\{APP_ID\}\}/g, escapeForJson(config.appId))
    .replace(/\{\{APP_NAME\}\}/g, escapeForJson(config.appName))
    .replace(/\{\{PROJECT_NAME\}\}/g, escapeForJson(config.projectName))
    .replace(/\{\{VERSION\}\}/g, escapeForJson(config.version))
    .replace(/\{\{BACKGROUND_HEX\}\}/g, escapeForJson(config.backgroundHex));
  await fse.writeFile(dest, substituted, 'utf8');
}

function escapeForJson(value: string): string {
  return value.replace(/\\/g, '\\\\').replace(/"/g, '\\"');
}

// ────────────────────────────────────────────────────────────────
// Capacitor shell node_modules — first-build install, cached
// ────────────────────────────────────────────────────────────────

const SHELL_INSTALL_MARKER = '.shell-deps-installed';

/** Install the Capacitor shell's dependencies inside `.capacitor/`.
 *  Cached via a marker file under `node_modules/` — subsequent
 *  invocations skip the install. To force a reinstall, delete the
 *  marker (or the entire `.capacitor/node_modules/` tree). */
async function installShellDeps(cacheDir: string): Promise<void> {
  const marker = join(cacheDir, 'node_modules', SHELL_INSTALL_MARKER);
  const lockfile = join(cacheDir, 'package-lock.json');
  const pkgManifest = join(cacheDir, 'package.json');
  if (await fse.pathExists(marker)) {
    // Cache hit. The marker tracks "install succeeded against this
    // manifest." If we upgraded the template's pinned Capacitor
    // version, the marker would still report installed — we re-
    // check the manifest's mtime against the marker's to detect
    // stale caches.
    const [manifestStat, markerStat] = await Promise.all([
      fse.stat(pkgManifest),
      fse.stat(marker),
    ]);
    if (manifestStat.mtimeMs <= markerStat.mtimeMs) {
      return; // Cache is fresh.
    }
    info('Capacitor shell manifest changed — reinstalling deps.');
  } else {
    info('Installing Capacitor shell dependencies (first-build only)…');
  }

  try {
    await execa('npm', ['install', '--silent', '--no-audit', '--no-fund'], {
      cwd: cacheDir,
      stdio: 'inherit',
    });
    await fse.ensureFile(marker);
    await fse.writeFile(marker, new Date().toISOString(), 'utf8');
    if (await fse.pathExists(lockfile)) {
      // We don't need the lockfile in the cache; deleting keeps
      // `.capacitor/` minimal.
    }
    success('Capacitor shell dependencies installed.');
  } catch {
    error('npm install inside .capacitor/ failed.');
    process.exit(1);
  }
}

// ────────────────────────────────────────────────────────────────
// Assets (icons + splash) — hash-cached @capacitor/assets generate
// ────────────────────────────────────────────────────────────────

async function ensureAssets(appDir: string, cacheDir: string): Promise<void> {
  const templateDir = locateTemplateDir();
  const sourceIcon = await pickSourceIcon(appDir, templateDir);
  const assetsDir = join(cacheDir, 'assets');
  const hashFile = join(assetsDir, '.source-hash');

  await fse.ensureDir(assetsDir);
  const sourceHash = await hashFileContents(sourceIcon);
  const cachedHash = (await fse.pathExists(hashFile))
    ? await fse.readFile(hashFile, 'utf8')
    : '';

  // The `@capacitor/assets` CLI requires the source to live at
  // `<cwd>/assets/icon-only.png` (or `icon.png` with a foreground
  // / background split). The single-icon path is the simplest;
  // splash screens reuse the same source with a colored
  // background.
  const stagedIcon = join(assetsDir, 'icon-only.png');
  await fse.copy(sourceIcon, stagedIcon);

  // Asset regen needs to run AFTER `cap add` since it writes into
  // the ios/ + android/ generated trees. We stage the source now;
  // the per-platform `runCapacitorAssetsGenerate` call below kicks
  // off the actual generation after platform projects exist.
  if (cachedHash !== sourceHash) {
    await fse.writeFile(hashFile, sourceHash, 'utf8');
  }
}

async function runCapacitorAssetsGenerate(
  cacheDir: string,
  platform: CapacitorPlatform,
): Promise<void> {
  // The `@capacitor/assets` package ships a `capacitor-assets`
  // binary. If `assets/icon-only.png` doesn't exist, the CLI errors
  // out — but we always stage it during `ensureAssets`.
  info(`Generating ${platform} icons via @capacitor/assets…`);
  try {
    await execa(
      'npx',
      ['capacitor-assets', 'generate', platform === 'ios' ? '--ios' : '--android'],
      { cwd: cacheDir, stdio: 'inherit' },
    );
    success('Asset generation complete.');
  } catch (cause) {
    // Non-fatal: a missing or malformed icon shouldn't block the
    // build. Apps that don't supply a `public/app-icon.png` use
    // Capacitor's built-in placeholder, which works for dev /
    // simulator runs and is replaced before App Store submission.
    warn('Asset generation failed; continuing with default icons.');
    if (cause instanceof Error) warn(cause.message);
  }
}

async function pickSourceIcon(
  appDir: string,
  templateDir: string,
): Promise<string> {
  const override = join(appDir, 'public', 'app-icon.png');
  if (await fse.pathExists(override)) return override;
  return join(templateDir, 'icons', 'icon.png');
}

async function hashFileContents(path: string): Promise<string> {
  const buf = await fse.readFile(path);
  return createHash('sha256').update(buf).digest('hex');
}

// ────────────────────────────────────────────────────────────────
// Web bundle handoff
// ────────────────────────────────────────────────────────────────

async function copyWebOutputToShell(
  appDir: string,
  cacheDir: string,
): Promise<void> {
  const src = join(appDir, 'out');
  const dest = join(cacheDir, 'www');
  if (!(await fse.pathExists(src))) {
    error(
      `Expected static export at ${src} but none was found. ` +
        "The web pipeline didn't produce an `out/` directory.",
    );
    process.exit(1);
  }
  info(`Copying web bundle: ${src} → ${dest}`);
  await fse.remove(dest);
  await fse.copy(src, dest);
}

// ────────────────────────────────────────────────────────────────
// Capacitor platform commands
// ────────────────────────────────────────────────────────────────

async function ensurePlatform(
  cacheDir: string,
  platform: CapacitorPlatform,
): Promise<void> {
  const platformDir = join(cacheDir, platform);
  if (await fse.pathExists(platformDir)) {
    return; // `cap add` is idempotent but slow; skip when already added.
  }
  info(`Adding Capacitor platform (${platform}) — first-build only…`);
  try {
    await execa('npx', ['cap', 'add', platform], {
      cwd: cacheDir,
      stdio: 'inherit',
    });
    success(`Platform ${platform} added.`);
  } catch {
    error(`\`cap add ${platform}\` failed.`);
    process.exit(1);
  }
}

async function runCapSync(
  cacheDir: string,
  platform: CapacitorPlatform,
): Promise<void> {
  info(`Running cap sync ${platform} (copy web + update native deps)…`);
  try {
    await execa('npx', ['cap', 'sync', platform], {
      cwd: cacheDir,
      stdio: 'inherit',
    });
    success(`cap sync ${platform} complete.`);
  } catch {
    error(`\`cap sync ${platform}\` failed.`);
    process.exit(1);
  }
  // Generate platform icons AFTER sync — the native projects now
  // exist for `@capacitor/assets` to write into.
  await runCapacitorAssetsGenerate(cacheDir, platform);
  // Re-run sync so the generated assets are picked up by the
  // native projects' resource compiles.
  try {
    await execa('npx', ['cap', 'copy', platform], {
      cwd: cacheDir,
      stdio: 'inherit',
    });
  } catch {
    // Non-fatal — the previous sync already wired the basics; the
    // copy is a belt-and-suspenders pass for the freshly-generated
    // icons.
  }
}

// ────────────────────────────────────────────────────────────────
// iOS build (Xcode)
// ────────────────────────────────────────────────────────────────

async function runIosBuild(cacheDir: string): Promise<void> {
  const iosDir = join(cacheDir, 'ios', 'App');
  const workspace = join(iosDir, 'App.xcworkspace');
  if (!(await fse.pathExists(workspace))) {
    error(
      `Expected Xcode workspace at ${workspace}. Was \`cap add ios\` successful?`,
    );
    process.exit(1);
  }

  info('Building iOS Simulator binary via xcodebuild…');
  // Simulator-targeted build doesn't require code signing. App
  // Store submission needs the user to open the workspace in
  // Xcode and configure a signing team — documented in
  // CLAUDE.md.
  try {
    await execa(
      'xcodebuild',
      [
        '-workspace',
        'App.xcworkspace',
        '-scheme',
        'App',
        '-configuration',
        'Release',
        '-sdk',
        'iphonesimulator',
        '-derivedDataPath',
        'build',
        'CODE_SIGNING_ALLOWED=NO',
      ],
      { cwd: iosDir, stdio: 'inherit' },
    );
    success('iOS Simulator build complete.');
  } catch (cause) {
    error('xcodebuild failed.');
    if (cause instanceof ExecaError && cause.code === 'ENOENT') {
      error(
        'Xcode Command Line Tools not found. Install with: xcode-select --install',
      );
    }
    process.exit(1);
  }
}

// ────────────────────────────────────────────────────────────────
// Android build (Gradle)
// ────────────────────────────────────────────────────────────────

async function runAndroidBuild(cacheDir: string): Promise<void> {
  const androidDir = join(cacheDir, 'android');
  const gradlew = join(androidDir, 'gradlew');
  if (!(await fse.pathExists(gradlew))) {
    error(
      `Expected Gradle wrapper at ${gradlew}. Was \`cap add android\` successful?`,
    );
    process.exit(1);
  }
  // Capacitor 6's `cap add android` ships gradlew with the executable
  // bit set; on systems where it's lost (rare — Windows or unzipped
  // tarballs), `chmod +x gradlew` is the recovery. We don't try to
  // chmod from the pipeline; surface a clear error if it isn't
  // executable.

  info('Building Android debug APK via ./gradlew assembleDebug…');
  try {
    await execa('./gradlew', ['assembleDebug'], {
      cwd: androidDir,
      stdio: 'inherit',
    });
    success('Android debug APK build complete.');
  } catch (cause) {
    error('Gradle build failed.');
    if (cause instanceof ExecaError && cause.code === 'ENOENT') {
      error(
        'gradlew not executable or missing. Try `chmod +x .capacitor/android/gradlew` if the file exists.',
      );
    }
    error(
      "Make sure JDK 17 + Android SDK are installed and ANDROID_HOME is set.",
    );
    process.exit(1);
  }
}

// ────────────────────────────────────────────────────────────────
// Reporting + dev-mode info
// ────────────────────────────────────────────────────────────────

async function reportBundleOutputs(
  cacheDir: string,
  platform: CapacitorPlatform,
): Promise<void> {
  if (platform === 'ios') {
    const productsDir = join(
      cacheDir,
      'ios',
      'App',
      'build',
      'Build',
      'Products',
      'Release-iphonesimulator',
    );
    if (await fse.pathExists(productsDir)) {
      info(`iOS Simulator build artifacts: ${productsDir}`);
      info(
        `  App bundle: ${join(productsDir, 'App.app')}`,
      );
      info(
        'Open the Xcode workspace at .capacitor/ios/App/App.xcworkspace to configure signing + archive for App Store submission.',
      );
    } else {
      warn(`Expected build output at ${productsDir} but none was found.`);
    }
    return;
  }

  const apkDir = join(
    cacheDir,
    'android',
    'app',
    'build',
    'outputs',
    'apk',
    'debug',
  );
  if (await fse.pathExists(apkDir)) {
    info(`Android debug APK: ${apkDir}`);
    info(
      'For Play Store release: configure a release signing config + run `./gradlew bundleRelease` to produce an `.aab`.',
    );
  } else {
    warn(`Expected APK output at ${apkDir} but none was found.`);
  }
}

async function runCapacitorDev(appDir: string): Promise<void> {
  info(
    'Capacitor dev mode runs the web pipeline. Test on mobile via:\n' +
      '  • PWA — open http://<your-local-ip>:3000 in mobile Safari / Chrome (Add to Home Screen).\n' +
      '  • Native debug — in another terminal: `pnpm build:ios` or `pnpm build:android`.\n' +
      '  • Live-reload-to-simulator is not wired in v1.',
  );
  await runWebPipeline({ appDir, mode: 'dev', target: 'capacitor' });
}

/** Reject iOS targets on non-macOS hosts. Xcode is macOS-only;
 *  failing fast with a clear message saves a minute of subprocess
 *  output before the same failure surfaces from `xcodebuild`. */
async function assertHostSupports(platform: CapacitorPlatform): Promise<void> {
  if (platform === 'ios' && process.platform !== 'darwin') {
    error(
      `iOS builds require macOS. Current host: ${process.platform}. ` +
        'Use a Mac or a macOS CI runner. The Android target works on Linux + Windows + macOS.',
    );
    process.exit(1);
  }
  return Promise.resolve();
}
